export interface ConnectorConfig {
  /** Slack Bot User OAuth Token with chat:write scope */
  slackBotToken: string
  /** Slack channel ID or name for sales routing (e.g., "C01SALESSID" or "#sales") */
  salesChannel: string
  /** Slack channel ID or name for support routing (e.g., "C01SUPPORTSID" or "#support") */
  supportChannel: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TwilioSmsPayload {
  MessageSid: string
  AccountSid: string
  From: string
  To: string
  Body: string
  NumMedia: string
  NumSegments: string
  [key: string]: string
}

export interface HandleResult {
  channel: string
  messageTs: string
  messageText: string
}

const SALES_KEYWORDS_REGEX = /pricing|quote|demo/i

function validatePayload(payload: TwilioSmsPayload): void {
  if (!payload.Body || typeof payload.Body !== 'string') {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From || typeof payload.From !== 'string') {
    throw new Error('Missing required field: From')
  }
}

async function postToSlack(
  config: ConnectorConfig,
  channel: string,
  text: string
): Promise<{ ok: boolean; channel: string; ts: string; message: { text: string; user: string; bot_id: string } }> {
  const fetchImpl = config.fetch ?? fetch
  const url = 'https://slack.com/api/chat.postMessage'
  const body = JSON.stringify({ channel, text })
  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at ${url}`)
  }

  return response.json() as Promise<{
    ok: boolean
    channel: string
    ts: string
    message: { text: string; user: string; bot_id: string }
  }>
}

export async function handle(payload: TwilioSmsPayload, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)

  const targetChannel = SALES_KEYWORDS_REGEX.test(payload.Body) ? config.salesChannel : config.supportChannel

  const result = await postToSlack(config, targetChannel, payload.Body)

  if (!result.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(result)}`)
  }

  return {
    channel: result.channel,
    messageTs: result.ts,
    messageText: result.message.text,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, TwilioSmsPayload } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TwilioSmsPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.channel).toBe('C01SALESSID')
    expect(result.messageText).toBe("Hi, I'd like a quote for pricing")
  })
})

describe('handle', () => {
  it('routes to sales channel when Body matches pricing keyword', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage' && req.json?.channel === 'C01SALESSID'
        ? jsonResponse(TARGET_ENDPOINTS[0].response)
        : jsonResponse({ error: 'unexpected call' }, 500)
    )
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Need pricing for enterprise plan',
    }
    const result = await handle(payload, config)
    expect(calls.length).toBe(1)
    expect(calls[0].json).toEqual({ channel: 'C01SALESSID', text: 'Need pricing for enterprise plan' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-token')
    expect(result.channel).toBe('C01SALESSID')
  })

  it('routes to sales channel when Body matches quote keyword', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage' && req.json?.channel === 'C01SALESSID'
        ? jsonResponse(TARGET_ENDPOINTS[0].response)
        : jsonResponse({ error: 'unexpected call' }, 500)
    )
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Can I get a quote?',
    }
    const result = await handle(payload, config)
    expect(calls[0].json).toEqual({ channel: 'C01SALESSID', text: 'Can I get a quote?' })
    expect(result.channel).toBe('C01SALESSID')
  })

  it('routes to sales channel when Body matches demo keyword (case insensitive)', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage' && req.json?.channel === 'C01SALESSID'
        ? jsonResponse(TARGET_ENDPOINTS[0].response)
        : jsonResponse({ error: 'unexpected call' }, 500)
    )
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Want a DEMO of the product',
    }
    const result = await handle(payload, config)
    expect(calls[0].json).toEqual({ channel: 'C01SALESSID', text: 'Want a DEMO of the product' })
    expect(result.channel).toBe('C01SALESSID')
  })

  it('routes to support channel when Body does not match sales keywords', async () => {
    const supportResponse = {
      ok: true,
      channel: 'C01SUPPORTSID',
      ts: '1717000001.000300',
      message: { text: 'General question', user: 'U02BOTUSER', bot_id: 'B02BOTUSER' },
    }
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage' && req.json?.channel === 'C01SUPPORTSID'
        ? jsonResponse(supportResponse)
        : jsonResponse({ error: 'unexpected call' }, 500)
    )
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'My internet is down',
    }
    const result = await handle(payload, config)
    expect(calls[0].json).toEqual({ channel: 'C01SUPPORTSID', text: 'My internet is down' })
    expect(result.channel).toBe('C01SUPPORTSID')
  })

  it('throws when Body is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 500))
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    const payload = { ...SOURCE_EXAMPLE, Body: undefined as unknown as string }
    await expect(handle(payload as unknown as TwilioSmsPayload, config)).rejects.toThrow('Missing required field: Body')
  })

  it('throws when From is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 500))
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    const payload = { ...SOURCE_EXAMPLE, From: undefined as unknown as string }
    await expect(handle(payload as unknown as TwilioSmsPayload, config)).rejects.toThrow('Missing required field: From')
  })

  it('throws on non-2xx response from Slack', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    const payload: TwilioSmsPayload = { ...SOURCE_EXAMPLE }
    await expect(handle(payload, config)).rejects.toThrow('Slack API error: 401 Unauthorized at https://slack.com/api/chat.postMessage')
    expect(calls.length).toBe(1)
  })

  it('throws when Slack returns ok=false', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ ok: false, error: 'channel_not_found' }, 200))
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    const payload: TwilioSmsPayload = { ...SOURCE_EXAMPLE }
    await expect(handle(payload, config)).rejects.toThrow('Slack API returned ok=false')
    expect(calls.length).toBe(1)
  })

  it('uses injected fetch instead of global fetch', async () => {
    let capturedFetch: typeof fetch | null = null
    const { fetch, calls } = fakeFetch((req) => {
      capturedFetch = fetch
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      salesChannel: 'C01SALESSID',
      supportChannel: 'C01SUPPORTSID',
      fetch,
    }
    await handle(SOURCE_EXAMPLE as unknown as TwilioSmsPayload, config)
    expect(capturedFetch).toBe(fetch)
  })
})

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://www.twilio.com/docs/messaging/guides/webhook-request
// Source: https://docs.slack.dev/reference/methods/chat.postMessage

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "MessageSid": "SMXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX",
  "AccountSid": "ACXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX",
  "From": "+14017122661",
  "To": "+15558675310",
  "Body": "Hi, I'd like a quote for pricing",
  "NumMedia": "0",
  "NumSegments": "1"
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://slack.com/api/chat.postMessage",
    "response": {
      "ok": true,
      "channel": "C01SALESSID",
      "ts": "1717000000.000200",
      "message": {
        "text": "Hi, I'd like a quote for pricing",
        "user": "U02BOTUSER",
        "bot_id": "B02BOTUSER"
      }
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  /** Slack Bot User OAuth Token with chat:write scope */
  slackBotToken: string
  /** Slack channel ID or name for sales routing (e.g., "C01SALESSID" or "#sales") */
  salesChannel: string
  /** Slack channel ID or name for support routing (e.g., "C01SUPPORTSID" or "#support") */
  supportChannel: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TwilioSmsPayload {
  MessageSid: string
  AccountSid: string
  From: string
  To: string
  Body: string
  NumMedia: string
  NumSegments: string
  [key: string]: string
}

export interface HandleResult {
  channel: string
  messageTs: string
  messageText: string
}

const SALES_KEYWORDS_REGEX = /pricing|quote|demo/i

function validatePayload(payload: TwilioSmsPayload): void {
  if (!payload.Body || typeof payload.Body !== 'string') {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From || typeof payload.From !== 'string') {
    throw new Error('Missing required field: From')
  }
}

async function postToSlack(
  config: ConnectorConfig,
  channel: string,
  text: string
): Promise<{ ok: boolean; channel: string; ts: string; message: { text: string; user: string; bot_id: string } }> {
  const fetchImpl = config.fetch ?? fetch
  const url = 'https://slack.com/api/chat.postMessage'
  const body = JSON.stringify({ channel, text })
  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at ${url}`)
  }

  return response.json() as Promise<{
    ok: boolean
    channel: string
    ts: string
    message: { text: string; user: string; bot_id: string }
  }>
}

export async function handle(payload: TwilioSmsPayload, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)

  const targetChannel = SALES_KEYWORDS_REGEX.test(payload.Body) ? config.salesChannel : config.supportChannel

  const result = await postToSlack(config, targetChannel, payload.Body)

  if (!result.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(result)}`)
  }

  return {
    channel: result.channel,
    messageTs: result.ts,
    messageText: result.message.text,
  }
}

