  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  /** Slack Bot User OAuth Token with chat:write scope */
  slackBotToken: string
  /** Slack channel ID or name for sales routing (e.g., "C01SALESSID" or "#sales") */
  salesChannel: string
  /** Slack channel ID or name for support routing (e.g., "C01SUPPORTSID" or "#support") */
  supportChannel: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TwilioSmsPayload {
  MessageSid: string
  AccountSid: string
  From: string
  To: string
  Body: string
  NumMedia: string
  NumSegments: string
  [key: string]: string
}

export interface HandleResult {
  channel: string
  messageTs: string
  messageText: string
}

const SALES_KEYWORDS_REGEX = /pricing|quote|demo/i

function validatePayload(payload: TwilioSmsPayload): void {
  if (!payload.Body || typeof payload.Body !== 'string') {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From || typeof payload.From !== 'string') {
    throw new Error('Missing required field: From')
  }
}

async function postToSlack(
  config: ConnectorConfig,
  channel: string,
  text: string
): Promise<{ ok: boolean; channel: string; ts: string; message: { text: string; user: string; bot_id: string } }> {
  const fetchImpl = config.fetch ?? fetch
  const url = 'https://slack.com/api/chat.postMessage'
  const body = JSON.stringify({ channel, text })
  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at ${url}`)
  }

  return response.json() as Promise<{
    ok: boolean
    channel: string
    ts: string
    message: { text: string; user: string; bot_id: string }
  }>
}

export async function handle(payload: TwilioSmsPayload, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)

  const targetChannel = SALES_KEYWORDS_REGEX.test(payload.Body) ? config.salesChannel : config.supportChannel

  const result = await postToSlack(config, targetChannel, payload.Body)

  if (!result.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(result)}`)
  }

  return {
    channel: result.channel,
    messageTs: result.ts,
    messageText: result.message.text,
  }
}

